const LOJAS_EXEMPLO = { cd: { nome: 'Centro de distribuição', cd: true }, cen: { nome: 'Loja Centro' }, sav: { nome: 'Loja Savassi' }, con: { nome: 'Loja Contagem' }, bet: { nome: 'Loja Betim' } };
