  const escala = { cen: { manha: 'Dra. Ana Prado', tarde: 'Dr. Luiz Melo', noite: '' }, sav: { manha: 'Dra. Bruna Reis', tarde: 'Dra. Bruna Reis', noite: 'Dr. Caio Lima' }, con: { manha: 'Dr. Paulo Sá', tarde: '', noite: '' }, bet: { manha: 'Dra. Rita Gomes', tarde: 'Dra. Rita Gomes', noite: '' } };
