  const inventario = [['cen', -12, 0.97, 18], ['sav', -5, 0.99, 25], ['con', -41, 0.88, -11], ['bet', -20, 0.95, 10]].map(([loja, ultimo, acur, prox]) => ({ loja, ultimo, acur, prox }));
  return { rede: 'Rede FarmaJá', loja: 'todas', lojasRede: JSON.parse(JSON.stringify(LOJAS_EXEMPLO)), lojas, transf, compra, precos, campanhas, perdas, controlados, pedidos, escala, turnos, inventario, regraPreco: 3, audit: [[quando(), 'Gerente Contagem', 'ajustou estoque de Rivotril 2 mg (−2) sem justificativa'], [quando(), 'Sistema', 'importou 18 notas de entrada do CD']].map(([q, quem, o]) => ({ q, quem, o })), plano: 'basico', resp: null };
